changeSet.sql:
CREATE UNIQUE INDEX UX_TrainerProfiles_TenantId_EmployeeCode ON app.TrainerProfiles (TenantId, EmployeeCode) WHERE EmployeeCode IS NOT NULL AND DeletedAt IS NULL;
CREATE TABLE app.TrainerMemberAssignments ( Id UNIQUEIDENTIFIER NOT NULL, TenantId UNIQUEIDENTIFIER NOT NULL, TrainerProfileId UNIQUEIDENTIFIER NOT NULL, MemberProfileId UNIQUEIDENTIFIER NOT NULL, StartDate DATE NOT NULL, EndDate DATE NULL, Status NVARCHAR(16) NOT NULL, AssignedByUserId UNIQUEIDENTIFIER NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_TrainerMemberAssignments PRIMARY KEY CLUSTERED (Id), CONSTRAINT FK_TrainerMemberAssignments_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id), CONSTRAINT FK_TrainerMemberAssignments_TrainerProfiles FOREIGN KEY (TrainerProfileId) REFERENCES app.TrainerProfiles (Id), CONSTRAINT FK_TrainerMemberAssignments_MemberProfiles FOREIGN KEY (MemberProfileId) REFERENCES app.MemberProfiles (Id), CONSTRAINT FK_TrainerMemberAssignments_Users FOREIGN KEY (AssignedByUserId) REFERENCES app.Users (Id), CONSTRAINT CK_TrainerMemberAssignments_Status CHECK (Status IN (N'Active', N'Ended')) ); CREATE UNIQUE INDEX UX_TrainerMemberAssignments_ActiveMember ON app.TrainerMemberAssignments (TenantId, MemberProfileId) WHERE Status = N'Active' AND DeletedAt IS NULL; CREATE INDEX IX_TrainerMemberAssignments_TrainerId ON app.TrainerMemberAssignments (TenantId, TrainerProfileId, Status) WHERE DeletedAt IS NULL;
CREATE TABLE app.TrainerTargets ( Id UNIQUEIDENTIFIER NOT NULL, TenantId UNIQUEIDENTIFIER NOT NULL, TrainerProfileId UNIQUEIDENTIFIER NOT NULL, TargetType NVARCHAR(32) NOT NULL, Period NVARCHAR(16) NOT NULL, PeriodStart DATE NOT NULL, PeriodEnd DATE NOT NULL, TargetValue DECIMAL(19, 4) NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_TrainerTargets PRIMARY KEY CLUSTERED (Id), CONSTRAINT FK_TrainerTargets_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id), CONSTRAINT FK_TrainerTargets_TrainerProfiles FOREIGN KEY (TrainerProfileId) REFERENCES app.TrainerProfiles (Id), CONSTRAINT CK_TrainerTargets_Type CHECK (TargetType IN (N'PtRevenue', N'PtSessions', N'NewPtClients')), CONSTRAINT CK_TrainerTargets_Period CHECK (Period IN (N'Monthly', N'Quarterly', N'Custom')), CONSTRAINT CK_TrainerTargets_Value CHECK (TargetValue > 0) ); CREATE UNIQUE INDEX UX_TrainerTargets_Period ON app.TrainerTargets (TenantId, TrainerProfileId, TargetType, PeriodStart, PeriodEnd) WHERE DeletedAt IS NULL;
CREATE TABLE app.TrainerIncentiveRules ( Id UNIQUEIDENTIFIER NOT NULL, TenantId UNIQUEIDENTIFIER NOT NULL, TargetType NVARCHAR(32) NOT NULL, IncentivePercent DECIMAL(9, 4) NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_TrainerIncentiveRules PRIMARY KEY CLUSTERED (Id), CONSTRAINT FK_TrainerIncentiveRules_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id), CONSTRAINT CK_TrainerIncentiveRules_Type CHECK (TargetType IN (N'PtRevenue', N'PtSessions', N'NewPtClients')), CONSTRAINT CK_TrainerIncentiveRules_Percent CHECK (IncentivePercent >= 0 AND IncentivePercent <= 100) ); CREATE UNIQUE INDEX UX_TrainerIncentiveRules_Tenant_Type ON app.TrainerIncentiveRules (TenantId, TargetType) WHERE DeletedAt IS NULL;
